def _validate_auth_token(auth_token):
    """Raise PermissionError when the request is not authenticated."""
    if auth_token is None or not is_valid_token(auth_token):
        raise PermissionError("invalid auth token")


def _validate_request_data(data):
    """Raise ValueError when the request has no payload."""
    if data is None:
        raise ValueError("request data is required")


def handle_request(data, auth_token):
    """Validate, authenticate, and process an incoming API request."""
    # Authenticate first so unauthenticated callers cannot use validation
    # errors to learn anything about the expected request payload.
    _validate_auth_token(auth_token)
    _validate_request_data(data)
    return process(data)

